create table public.active_facility_context(user_id uuid primary key references auth.users(id) on delete cascade,facility_id uuid not null references public.facilities(id) on delete cascade,selected_at timestamptz not null default now());
alter table public.active_facility_context enable row level security;
create policy active_context_own_read on public.active_facility_context for select to authenticated using(user_id=(select auth.uid()));
create policy active_context_own_insert on public.active_facility_context for insert to authenticated with check(user_id=(select auth.uid()) and (private.is_platform_root() or private.is_facility_member(facility_id)));
create policy active_context_own_update on public.active_facility_context for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()) and (private.is_platform_root() or private.is_facility_member(facility_id)));
grant select,insert,update on public.active_facility_context to authenticated;

create or replace function private.is_active_facility(fid uuid) returns boolean language sql stable security definer set search_path='' as $$ select private.is_platform_root() or exists(select 1 from public.active_facility_context c where c.user_id=(select auth.uid()) and c.facility_id=fid) $$;
revoke all on function private.is_active_facility(uuid) from public,anon;grant execute on function private.is_active_facility(uuid) to authenticated;
create table public.patient_intake_drafts(user_id uuid not null references auth.users(id) on delete cascade,facility_id uuid not null references public.facilities(id) on delete cascade,draft_data jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now(),primary key(user_id,facility_id));
alter table public.patient_intake_drafts enable row level security;
create policy intake_drafts_own on public.patient_intake_drafts for all to authenticated using(user_id=(select auth.uid()) and private.is_active_facility(facility_id)) with check(user_id=(select auth.uid()) and private.is_active_facility(facility_id));
grant select,insert,update,delete on public.patient_intake_drafts to authenticated;

create table public.deleted_record_archive(id bigint generated by default as identity primary key,source_table text not null,record_key jsonb not null,record_data jsonb not null,deleted_by uuid references auth.users(id),deleted_by_name text not null,deleted_at timestamptz not null default now());
create table public.record_change_audit(id bigint generated by default as identity primary key,source_table text not null,operation text not null check(operation in ('INSERT','UPDATE','DELETE')),record_key jsonb not null,before_data jsonb,after_data jsonb,changed_by uuid references auth.users(id),changed_by_name text not null,changed_at timestamptz not null default now());
alter table public.deleted_record_archive enable row level security;alter table public.record_change_audit enable row level security;
create policy deleted_archive_authorized_read on public.deleted_record_archive for select to authenticated using(private.is_platform_root() or exists(select 1 from public.patients p where p.id=(record_data->>'patient_id')::bigint and p.facility_id is not null and private.is_active_facility(p.facility_id) and private.is_facility_member(p.facility_id)));
create policy change_audit_authorized_read on public.record_change_audit for select to authenticated using(private.is_platform_root() or changed_by=(select auth.uid()));
grant select on public.deleted_record_archive,public.record_change_audit to authenticated;

create or replace function private.archive_record_change() returns trigger language plpgsql security definer set search_path='' as $$
declare actor uuid:=(select auth.uid());actor_name text;payload jsonb;key_data jsonb;
begin select coalesce(p.display_name,p.email,actor::text,'System') into actor_name from public.profiles p where p.user_id=actor;actor_name:=coalesce(actor_name,actor::text,'System');payload:=case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;key_data:=jsonb_build_object('id',payload->'id');insert into public.record_change_audit(source_table,operation,record_key,before_data,after_data,changed_by,changed_by_name) values(tg_table_name,tg_op,key_data,case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) end,case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) end,actor,actor_name);if tg_op='DELETE' then insert into public.deleted_record_archive(source_table,record_key,record_data,deleted_by,deleted_by_name) values(tg_table_name,key_data,to_jsonb(old),actor,actor_name);return old;end if;return new;end $$;
revoke all on function private.archive_record_change() from public,anon,authenticated;
do $$ declare t text;begin foreach t in array array['patients','encounters','orders','medication_orders','clinical_notes','diagnoses','vital_sign_observations','prenatal_episodes','prenatal_visits','partographs','partograph_observations'] loop execute format('drop trigger if exists archive_record_change on public.%I',t);execute format('create trigger archive_record_change after insert or update or delete on public.%I for each row execute function private.archive_record_change()',t);end loop;end $$;

alter policy patients_facility_read on public.patients using(private.is_platform_root() or (facility_id is not null and private.is_active_facility(facility_id) and private.is_facility_member(facility_id)) or exists(select 1 from public.patient_accounts pa where pa.user_id=(select auth.uid()) and pa.patient_id=patients.id) or exists(select 1 from public.patient_accounts pa join public.patient_proxies px on px.proxy_patient_id=pa.patient_id where pa.user_id=(select auth.uid()) and px.target_patient_id=patients.id and px.can_view and px.active));
alter policy patients_facility_create on public.patients with check(private.is_platform_root() or (facility_id is not null and private.is_active_facility(facility_id) and private.is_facility_member(facility_id)));
alter policy patients_facility_update on public.patients using(private.is_platform_root() or (facility_id is not null and private.is_active_facility(facility_id) and private.is_facility_member(facility_id))) with check(private.is_platform_root() or (facility_id is not null and private.is_active_facility(facility_id) and private.is_facility_member(facility_id)));
alter policy vitals_access on public.vital_sign_observations using(private.is_aal2() and private.is_active_facility(facility_id) and private.is_facility_member(facility_id)) with check(private.is_aal2() and private.is_active_facility(facility_id) and private.is_facility_member(facility_id));
alter policy queues_access on public.care_queue_entries using(private.is_aal2() and private.is_active_facility(facility_id) and private.is_facility_member(facility_id)) with check(private.is_aal2() and private.is_active_facility(facility_id) and private.is_facility_member(facility_id));
alter policy prenatal_access on public.prenatal_episodes using(private.is_aal2() and private.is_active_facility(facility_id) and private.is_facility_member(facility_id)) with check(private.is_aal2() and private.is_active_facility(facility_id) and private.is_facility_member(facility_id));
create index active_context_facility_idx on public.active_facility_context(facility_id);create index deleted_archive_patient_idx on public.deleted_record_archive(((record_data->>'patient_id')),deleted_at desc);create index record_change_source_time_idx on public.record_change_audit(source_table,changed_at desc);
